  ('OVERSHIRT', 'Camisa-jaqueta', 'Overshirt', 'Camisa encorpada usada aberta como terceira peça (shacket).'),
  ('OVERSIZED', 'Oversized', 'Oversized', 'Propositalmente maior que o corpo: ombro caído, corpo e mangas amplos e mais compridos.'),
  ('OVERSIZED_FRAME', 'Lentes grandes', 'Oversized', 'Armação e lentes bem maiores que o rosto.'),
  ('PACKABLE', 'Dobrável', 'Packable', 'Guarda-se no próprio bolso ou saquinho.'),
  ('PALAZZO', 'Palazzo', 'Palazzo', 'Extremamente larga e fluida desde o quadril, até o chão.'),
  ('PAPERBAG', 'Clochard', 'Paperbag', 'Cintura alta franzida por cinto/amarração, formando babado acima do cós.'),
  ('PARACHUTE', 'Parachute', 'Parachute', 'Nylon leve, muito larga, com cordões/reguladores na barra.'),
  ('PEACOAT', 'Japona', 'Peacoat', 'Curto, transpassado, de lã grossa e gola larga.'),
  ('PEASANT', 'Bata', 'Peasant', 'Ampla e leve, decote franzido e mangas soltas ou bufantes (camponesa).'),
  ('PENCIL', 'Lápis', 'Pencil', 'Justa e reta, afinando levemente em direção à barra.'),
  ('PENDANT_NECKLACE', 'Pingente', 'Pendant', 'Corrente com um pingente ou medalha.'),
  ('PENNY', 'Penny', 'Penny', 'Tira sobre o peito do pé com recorte em losango.'),
  ('PEPLUM', 'Peplum', 'Peplum', 'Babado/godê na cintura que se abre sobre o quadril.'),
  ('PERFORMANCE', 'Performance', 'Performance', 'Tecnologia atual de amortecimento e tração para jogo.'),
  ('PHONE_BAG', 'Porta-celular', 'Phone bag', 'Mini bolsa do tamanho do celular.'),
  ('PINAFORE', 'Salopete', 'Pinafore', 'Vestido com peitilho e alças, usado sobre blusa (jardineira-vestido).'),
  ('PIN_BUCKLE', 'Fivela de pino', 'Pin buckle', 'Fivela tradicional com pino nos furos.'),
  ('PLAIN_TOE', 'Bico liso', 'Plain toe', 'Biqueira sem costura nem ornamento.'),
  ('PLATE_BUCKLE', 'Fivela placa', 'Plate buckle', 'Fivela em placa ou monograma, sem pino aparente.'),
  ('PLEATED', 'Plissada', 'Pleated', 'Pregas prensadas ao longo de toda a peça.'),
  ('POUCH', 'Pouch', 'Pouch', 'Macia, franzida ou lisa, sem estrutura.'),
  ('PRE_TIED_BOW', 'Nó pronto', 'Pre-tied', 'Gravata-borboleta já atada, com regulador.'),
  ('PUFFER', 'Puffer', 'Puffer', 'Acolchoado em gomos com enchimento (pluma ou sintético).'),
  ('PUMP', 'Scarpin', 'Pump', 'Fechado, decotado no peito do pé, sem tiras.'),
  ('QUILTED', 'Matelassê', 'Quilted', 'Pespontos em losango ou linhas, achatado, com pouco enchimento.'),
  ('RACERBACK', 'Nadador', 'Racerback', 'Alças que se encontram no meio das costas, deixando as escápulas livres.'),
  ('RACING', 'Competição', 'Racing', 'Leve, com placa (carbono) e drop baixo.'),
  ('RAIN_BOOT', 'Galocha', 'Rain boot', 'Borracha moldada impermeável.'),
  ('RAIN_JACKET', 'Capa de chuva', 'Rain jacket', 'Impermeável com costuras seladas e capuz.'),
  ('RECTANGLE_FRAME', 'Retangular', 'Rectangle', 'Mais largo que alto, perfil estreito.'),
  ('REGULAR', 'Regular', 'Regular', 'Caimento tradicional, folga moderada: nem justo nem largo.'),
  ('RELAXED', 'Relaxed', 'Relaxed', 'Mais folga no corpo (na calça, quadril e coxa folgados), sem chegar a oversized/baggy.'),
  ('RETRO_RUNNER', 'Retrô de corrida', 'Retro runner', 'Silhueta de corrida dos anos 70–90 em camurça/nylon (ex.: NB 574).'),
  ('REVERSIBLE_BELT', 'Dupla face', 'Reversible', 'Duas faces de cor/acabamento com fivela giratória.'),
  ('RIDING', 'Montaria', 'Riding', 'Cano alto liso e justo, bico redondo e salto baixo.'),
  ('ROLLTOP', 'Rolltop', 'Rolltop', 'Abertura que enrola e fecha com fivela.'),
  ('ROUND_FRAME', 'Redondo', 'Round', 'Lentes circulares.'),
  ('RUCKSACK', 'Mochila com aba', 'Rucksack', 'Abertura com cordão sob aba com fivelas.'),
  ('RUGBY', 'Rugby', 'Rugby', 'Polo de manga longa em malha encorpada e gola de tecido plano.'),
  ('SADDLE_BAG', 'Saddle', 'Saddle bag', 'Formato de sela, com aba arredondada.'),
  ('SADDLE_SHOE', 'Saddle', 'Saddle shoe', 'Faixa de couro contrastante sobre o peito do pé.'),
  ('SAFARI', 'Safári', 'Safari', 'Cintura marcada por cinto, quatro bolsos e dragonas.'),
  ('SAILOR', 'Marinheiro', 'Sailor', 'Cintura alta, perna larga e abotoamento frontal duplo.'),
  ('SATCHEL', 'Satchel', 'Satchel', 'Estruturada, base larga, alça de mão e alça transversal removível.'),
  ('SCAPULAR', 'Escapulário', 'Scapular', 'Dois pingentes ligados, um na frente e outro nas costas.'),
  ('SCRUNCHIE', 'Xuxinha', 'Scrunchie', 'Elástico revestido de tecido franzido.'),
  ('SEAMLESS', 'Sem costura', 'Seamless', 'Malha tubular contínua, sem costuras laterais.'),
  ('SELF_TIE_BOW', 'Para dar nó', 'Self-tie', 'Gravata-borboleta que se amarra à mão.'),
  ('SEMI_BROGUE', 'Semi brogue', 'Semi-brogue', 'Biqueira reta com perfurações e medalhão na ponta.'),
  ('SHAPING', 'Modelador', 'Shaping', 'Body de compressão que modela cintura e abdômen.'),
  ('SHEATH', 'Tubinho', 'Sheath', 'Justo e reto acompanhando o corpo (pences), sem recorte na cintura.'),
  ('SHELL', 'Shell', 'Shell', 'Casca corta-vento/impermeável leve, sem enchimento.'),
  ('SHIELD', 'Máscara', 'Shield', 'Lente única contínua cobrindo os dois olhos.'),
  ('SHIFT', 'Reto', 'Shift', 'Solto, sem marcar a cintura, caindo reto dos ombros.'),
  ('SHIRT_DRESS', 'Chemise', 'Shirt dress', 'Abotoamento frontal, gola e punhos de camisa.'),
  ('SHOPPER', 'Shopper', 'Shopper', 'Aberta, grande, com alças longas de ombro.'),
  ('SIGNET', 'Chevalier', 'Signet', 'Face plana gravável (brasão, iniciais).'),
  ('SKATER', 'Skater', 'Skater', 'Gancho longo, perna larga e levemente afunilada, um pouco mais curta (C&A/Renner).'),
  ('SKINNY', 'Skinny', 'Skinny', 'Justa do quadril ao tornozelo, colada na perna (na legging, a forma tradicional).'),
  ('SKINNY_SCARF', 'Twilly', 'Skinny scarf', 'Tira estreita amarrada no pescoço ou na alça da bolsa.'),
  ('SKINNY_TIE', 'Gravata fina', 'Skinny tie', 'Largura em torno de 4–5 cm.'),
  ('SLIDE', 'Slide', 'Slide', 'Uma tira larga sobre o peito do pé.'),
  ('SLIM', 'Slim', 'Slim', 'Justa sem apertar, com pouca folga; na calça, perna estreita que afina de leve até a barra.'),
  ('SLIM_TIE', 'Gravata slim', 'Slim tie', 'Largura em torno de 6 cm.'),
  ('SLINGBACK', 'Slingback', 'Slingback', 'Frente fechada e calcanhar aberto com tira.'),
  ('SLING_BAG', 'Sling', 'Sling bag', 'Alça única cruzando o peito ou as costas.'),
  ('SLIP', 'Slip', 'Slip', 'Cortado no viés, fluido e rente ao corpo (no vestido, de alças finas, como camisola).'),
  ('SLIPPER', 'Slipper', 'Slipper', 'Sapato baixo de calce fácil, cabedal macio (veludo/couro) sem cadarço.'),
  ('SLOUCH', 'Slouch', 'Slouch', 'Cano largo e mole que forma dobras (sanfonado).'),
  ('SLOUCHY_BEANIE', 'Gorro caído', 'Slouchy beanie', 'Comprido, com sobra caída atrás.'),
  ('SLOUCHY_TOTE', 'Tote molenga', 'Slouchy tote', 'Tote macia que cede quando cheia.'),
  ('SMARTWATCH', 'Smartwatch', 'Smartwatch', 'Tela conectada ao celular.'),
  ('SMOCKED', 'Lastex', 'Smocked', 'Corpo franzido com elástico (smock/lastex), ajusta sem fechamento.'),
  ('SNEAKER_BOOT', 'Tênis botinha', 'Sneaker boot', 'Tênis com cano de bota acima do tornozelo.'),
  ('SNORKEL', 'Snorkel', 'Snorkel', 'Capuz que fecha em túnel sobre o rosto.'),
  ('SNOW_BOOT', 'Bota de neve', 'Snow boot', 'Cano forrado de pelo ou lã e sola de inverno.'),
  ('SOCK_BOOT', 'Bota meia', 'Sock boot', 'Cano de malha elástica justo na perna, sem fechamento.'),
  ('SOCK_SNEAKER', 'Tênis meia', 'Sock sneaker', 'Cabedal de malha elástica que veste como meia.'),
  ('SOLITAIRE', 'Solitário', 'Solitaire', 'Uma pedra central em destaque.'),
  ('SPORTS_BRA', 'Top esportivo', 'Sports bra', 'Top de sustentação para atividade física.'),
  ('SPORT_SANDAL', 'Papete', 'Sport sandal', 'Tiras largas de velcro/nylon e solado esportivo.'),
  ('SQUARE_FRAME', 'Quadrado', 'Square', 'Altura e largura parecidas, cantos retos.'),
  ('SQUARE_SCARF', 'Lenço', 'Square scarf', 'Lenço quadrado (seda, carré).'),
  ('STABILITY', 'Estabilidade', 'Stability', 'Suporte medial para pisada pronada.'),
  ('STATEMENT_EARRING', 'Maxi brinco', 'Statement', 'Grande e chamativo, peça principal do look.'),
  ('STATEMENT_NECKLACE', 'Maxi colar', 'Statement', 'Grande e chamativo.'),
  ('STIRRUP', 'Com pezinho', 'Stirrup', 'Alça sob o pé que segura a barra.'),
  ('STRAIGHT', 'Reta', 'Straight', 'Mesma largura do joelho à barra, sem afunilar nem abrir (na saia, reta/secretária).'),
  ('STRAND_NECKLACE', 'Fio de contas', 'Strand', 'Contas ou pérolas enfiadas num fio.'),
  ('STRAPPY', 'Tiras', 'Strappy', 'Várias tiras cruzadas nas costas ou nos ombros (na sandália, várias tiras finas sobre o pé).'),
  ('STRUCTURED_TOTE', 'Tote estruturada', 'Structured tote', 'Tote rígida, com base firme e laterais retas.'),
  ('STUD', 'Ponto de luz', 'Stud', 'Fixo no lóbulo, sem pendente.'),
  ('SUIT', 'Terno / tailleur', 'Suit', 'Blazer com calça ou saia do mesmo tecido.'),
  ('TAILORED_VEST', 'Colete de alfaiataria', 'Tailored vest', 'Colete de terno (waistcoat), com botões e decote em V.'),
  ('TAPERED', 'Afunilada', 'Tapered', 'Folga no quadril e coxa, estreitando aos poucos até o tornozelo.'),
  ('TASSEL', 'Tassel', 'Tassel', 'Borlas (pingentes de franja) no peito do pé.');
INSERT INTO taxonomy_variations (code, display_name_pt_br, display_name_en, description_pt_br) VALUES
  ('TECH_RUNNER', 'Tech runner', 'Tech runner', 'Tela técnica e entressola de corrida em visual lifestyle Y2K.'),
  ('TENNIS_BRACELET', 'Riviera', 'Tennis', 'Fileira contínua de pedras.'),
  ('TENNIS_NECKLACE', 'Riviera', 'Tennis', 'Fileira contínua de pedras.'),
  ('TERRACE', 'Terrace', 'Terrace', 'Perfil baixo e fino, biqueira em T e sola de goma (ex.: Samba, Gazelle).'),
  ('THONG', 'De dedo', 'Thong', 'Tira em V presa entre os dedos.'),
  ('THREADER', 'Brinco de fio', 'Threader', 'Corrente fina que atravessa o furo e pende.'),
  ('THREE_PIECE', 'Terno três peças', 'Three-piece suit', 'Blazer, colete e calça.'),
  ('TIERED', 'Camadas', 'Tiered', 'Faixas horizontais franzidas sobrepostas (estilo prairie).'),
  ('TIE_FRONT', 'Amarração frontal', 'Tie-front', 'Barra ou decote com nó/laço na frente.'),
  ('TIGHTS', 'Meia-calça', 'Tights', 'Meia-calça da cintura aos pés.'),
  ('TOE_SOCK', 'Dedinhos', 'Toe socks', 'Cada dedo separado.'),
  ('TOP_AND_PANTS', 'Conjunto com calça', 'Pant set', 'Parte de cima e calça do mesmo tecido/estampa.'),
  ('TOP_AND_SHORTS', 'Conjunto com short', 'Shorts set', 'Parte de cima e short do mesmo tecido/estampa.'),
  ('TOP_AND_SKIRT', 'Conjunto com saia', 'Skirt set', 'Parte de cima e saia do mesmo tecido/estampa.'),
  ('TOP_HANDLE', 'Alça de mão', 'Top handle', 'Estruturada, com alça curta superior para a mão ou o antebraço.'),
  ('TRACK', 'Agasalho', 'Track', 'Jaqueta de treino em malha ou tactel, com zíper e gola alta.'),
  ('TRACKSUIT', 'Agasalho completo', 'Tracksuit', 'Jaqueta + calça de treino ou conjunto de moletom.'),
  ('TRACK_SPIKE', 'Sapatilha de atletismo', 'Track spike', 'Sola rígida com pregos para pista.'),
  ('TRAIL', 'Trail', 'Trail', 'Solado com cravos e proteção para terra/montanha.'),
  ('TRAPEZE', 'Trapézio', 'Trapeze', 'Estreito nos ombros e abrindo muito até a barra, sem cintura.'),
  ('TRENCH', 'Trench coat', 'Trench', 'Transpassado, com cinto, pala de tempestade e dragonas.'),
  ('TRIFOLD', 'Três dobras', 'Trifold', 'Carteira de três dobras.'),
  ('TRILBY', 'Trilby', 'Trilby', 'Como o fedora, mas com aba curta virada para baixo atrás.'),
  ('TRUCKER', 'Trucker', 'Trucker', 'Jaqueta jeans clássica: bolsos de aba no peito, pences verticais e cós com botões.'),
  ('TRUCKER_CAP', 'Trucker', 'Trucker', 'Frente de espuma e traseira de tela.'),
  ('TRUE_MOC', 'Mocassim tradicional', 'True moccasin', 'Peça única de couro envolvendo o pé, costura em U, sem salto.'),
  ('TULIP', 'Tulipa', 'Tulip', 'Transpassada na frente, volume no quadril e barra fechando em pétala.'),
  ('TUNIC', 'Túnica', 'Tunic', 'Blusa longa e reta que cobre o quadril, vestida pela cabeça.'),
  ('TUTU', 'Tutu', 'Tutu', 'Camadas de tule armado.'),
  ('TUXEDO_SHIRT', 'Camisa de smoking', 'Tuxedo shirt', 'Peitilho com pregas ou nervuras e punho duplo.'),
  ('T_SHIRT_DRESS', 'Vestido camiseta', 'T-shirt dress', 'Corpo de camiseta alongado, reto, em malha.'),
  ('T_STRAP', 'Tira em T', 'T-strap', 'Tira central no peito do pé ligada à tira do tornozelo.'),
  ('UNSTRUCTURED', 'Desestruturado', 'Unstructured', 'Sem ombreira nem entretela rígida, caimento macio.'),
  ('UTILITY', 'Utilitário', 'Utility', 'Muitos bolsos aplicados, estilo militar/workwear.'),
  ('VARSITY', 'College', 'Varsity', 'Corpo de lã com mangas contrastantes, botões de pressão e ribanas listradas.'),
  ('VENETIAN', 'Veneziano', 'Venetian', 'Liso, sem tira nem ornamento.'),
  ('VISOR', 'Viseira', 'Visor', 'Só a aba e a faixa, sem copa.'),
  ('VULCANIZED', 'Vulcanizado', 'Vulcanized', 'Sola fina vulcanizada e biqueira de borracha; flexível (lona: All Star, Vans).'),
  ('WALKING', 'Caminhada', 'Walking', 'Amortecimento confortável e solado flexível para caminhar.'),
  ('WAYFARER', 'Wayfarer', 'Wayfarer', 'Acetato com topo mais largo que a base (trapezoidal).'),
  ('WEB_BELT', 'Lona', 'Web', 'Tira de lona/nylon com fivela de pressão ou de trava.'),
  ('WEIGHTLIFTING', 'LPO', 'Weightlifting', 'Salto rígido elevado e tira de ajuste para levantamento de peso.'),
  ('WESTERN', 'Texana', 'Western', 'Bico fino, salto cubano e cano com pesponto decorativo.'),
  ('WESTERN_BELT', 'Country', 'Western', 'Couro trabalhado com fivela grande ornamentada.'),
  ('WESTERN_SHIRT', 'Camisa western', 'Western shirt', 'Pala recortada na frente/costas, bolsos com aba e botões de pressão.'),
  ('WHOLECUT', 'Peça única', 'Wholecut', 'Cabedal de uma única peça de couro, sem costuras aparentes.'),
  ('WIDE_BELT', 'Faixa', 'Wide/waist', 'Largo, marcando a cintura sobre vestidos e casacos (obi/corset).'),
  ('WIDE_LEG', 'Wide leg', 'Wide leg', 'Cintura ajustada e perna larga e reta desde a coxa (pantalona).'),
  ('WINGTIP', 'Brogue', 'Wingtip', 'Biqueira em forma de asa (W) com perfurações (full brogue).'),
  ('WORK_BOOT', 'Botina', 'Work boot', 'Robusta, de amarrar, com biqueira reforçada e sola grossa.'),
  ('WRAP', 'Transpassado', 'Wrap', 'Frente cruzada (envelope) que fecha amarrando ou com faixa na lateral.'),
  ('WRAPAROUND', 'Envolvente', 'Wraparound', 'Armação curva que envolve a lateral do rosto (esportivo).'),
  ('WRISTLET', 'Clutch de pulso', 'Wristlet', 'Pequena, com alça de pulso.');
